      <section class="mt-7"><div class="mb-3 flex items-end justify-between gap-3"><div><h2 class="m-0 text-2xl font-bold">Ofertas para explorar</h2><p class="mb-0 mt-1 text-sm text-slate-600">Precios de ejemplo, no cotizaciones comerciales.</p></div><button class="secondary" onclick={()=>go('ganado')}>Ver catálogo</button></div><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{#each listings.slice(0,3) as item}<article class="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm"><span class="text-xs font-bold uppercase text-emerald-800">{item.category} · {item.department}</span><h3 class="mb-2 mt-3 text-lg">{item.title}</h3><p class="text-sm text-slate-600">{item.quantity}</p><p class="text-xl font-extrabold">S/ {item.price.toLocaleString('es-PE')} <small class="text-xs font-normal text-slate-500">estimado</small></p><button onclick={()=>buy(item)}>Comprar en demo</button></article>{/each}</div></section>
    {:else if active==='ganado'}
