tURL);photoUrls=[];}}>Limpiar</button></div></form><aside class="rounded-2xl border border-stone-200 bg-white p-5"><h2 class="m-0 text-lg font-bold">Antes de publicar</h2><ol class="mt-3 list-inside list-decimal space-y-3 text-sm leading-6 text-slate-600"><li>Usa fotos nítidas y propias.</li><li>Indica la cantidad y unidad de medida.</li><li>Escribe un precio referencial claro.</li><li>Comprueba el departamento elegido.</li><li>Publica y valida cómo aparece en el catálogo.</li></ol><p class="mt-5 rounded-lg bg-amber-50 p-3 text-xs leading-5 text-amber-900">En esta demo las fotos no salen del navegador y los datos no se envían a la API.</p></aside></section>
    {:else if active==='compras'}
      <section class="mt-6 rounded-2xl border border-stone-200 bg-white p-5 sm:p-7"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="m-0 text-xl font-bold">Mis compras de demostración</h2><p class="mb-0 mt-1 text-sm text-slate-600">Progreso ilustrativo que cambia en el navegador.</p></div><span class="rounded-full bg-amber-100 px-3 py-1 text-xs font-bold text-amber-900">SIN PAGOS NI ÓRDENES REALES</span></div>{#if purchases.length===0}<div class="mt-5 rounded-xl border border-dashed border-stone-300 p-8 text-center"><p class="text-slate-600">Todavía no hay compras de prueba.</p><button onclick={()=>go('ganado')}>Explorar lotes</button></div>{:else}<div class="mt-5 space-y-4">{#each purchases as purchase (purchase.id)}<article class="rounded-xl border border-stone-200 p-5"><div class="flex flex-wrap justify-between gap-2"><div><span class="text-xs font-bold text-emerald-800">{purchase.id} · DEMO</span><h3 class="mb-1 mt-2 text-lg">{purchase.title}</h3><p class="m-0 text-sm text-slate-600">Destino referencial: {purchase.department} · S/ {purchase.price.toLocaleString('es-PE')} estimado</p></div><span class="text-xs text-slate-500">{purchase.created}</span></div><ol class="mt-5 grid gap-2 sm:grid-cols-4">{#each purchaseSteps as step,i}<li class="rounded-lg p-3 text-xs font-semibold {i<=purchase.status?'bg-emerald-100 text-emerald-950':'bg-stone-100 text-slate-500'}"><span class="block text-base">{i<purchase.status?'✓':i===purchase.status?'●':'○'}</span>{step}</li>{/each}</ol></article>{/each}</div>{/if}<p class="mt-5 text-xs text-slate-500">El seguimiento no usa GPS, transportistas ni eventos logísticos reales. Se reinicia si borras los datos locales del navegador.</p></section>
    {/if}
  </main><footer class="border-t border-stone-200 bg-white px-4 py-5 text-center text-xs text-slate-500">GANADITO · Vista previa MVP · Todas las operaciones mostradas son simuladas y locales.</footer>
</div>
